return items.map(item => {
  const data = item.json;

  return {
    json: {
      pageContent: `Categoría: ${data.categoria}
Pregunta: ${data.pregunta}
Respuesta: ${data.respuesta}`,
      metadata: {
        categoria: data.categoria,
        fuente: data.fuente,
        vigente: data.vigente
      }
    }
  };
});

return items
  .map(item => {
    const data = item.json;

    const content = data.faq ?? data.pageContent ?? '';

    return {
      json: {
        content,
        metadata: data.metadata ?? {
          source: data.source ?? 'FAQ_RRHH_demo'
        }
      }
    };
  })
  .filter(item => item.json.content.trim() !== '');
